def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
                if prev['bid'] >= 120 and opp.get('budget', 0) > 100:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 7:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
    elif urgency >= 5:
        bid = max(0.78 * DAILY_SALARY, min(highest_prev + 1.5, 0.95 * DAILY_SALARY))
    elif urgency >= 3:
        if highest_prev >= 150:
            bid = 46.0
        else:
            bid = max(38.0, min(highest_prev + 1.0, 58.0))
    else:
        if highest_prev >= 150:
            bid = 24.0 if loose_supply else 31.0
        elif highest_prev >= 110:
            bid = 30.0 if loose_supply else 37.0
        elif highest_prev >= 70:
            bid = 36.0 if loose_supply else 43.0
        else:
            bid = max(32.0, avg_prev * 0.75 if avg_prev > 0 else 35.0)

    if rich_aggressive >= 2 and urgency <= 3:
        bid *= 0.9

    if day >= 8:
        if hp <= 4 or no_water >= 1:
            bid = max(bid, 0.82 * DAILY_SALARY)
        else:
            bid = min(bid, 0.75 * DAILY_SALARY)

    if budget < bid:
        if hp <= 2 or no_water >= 2:
            bid = budget
        else:
            bid = min(budget, max(0.0, bid * 0.85))

    if budget <= 0:
        return 0.0

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, bid conservatively
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    yesterday_by_op = {}
    for oid, o in opponents_status.items():
        if not o.get('alive', False):
            continue
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_val = float(bid)
            except Exception:
                continue
            yesterday_bids.append(bid_val)
            yesterday_by_op[oid] = bid_val

    # Determine threat level from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Base bid depends on urgency
    # If low HP or already accumulating no-water days, be more aggressive.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4 or my_no_water_days == 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.50

    # Exploit observed aggression: if someone previously bid near top, we need to outbid slightly.
    # Otherwise, undercut and rely on them overpaying.
    # Use supply to scale: when supply is high, we can bid lower.
    supply_scale = 0.9 if supply <= 18.0 else (1.0 if supply <= 21.0 else 0.85)

    # Target bid logic
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        # Very aggressive field yesterday: bid to secure with slight margin.
        target = min(highest_prev_bid, second_prev_bid + 5.0)
        target = max(target, base)
    elif highest_prev_bid >= DAILY_SALARY * 1.1:
        # Moderate aggression: bid around base but try to beat second-highest.
        target = max(base, second_prev_bid + 2.5)
    else:
        # Generally conserved: bid around base, slightly reduced if supply is ample.
        target = base * supply_scale

    # Cap by budget and ensure non-negative
    bid = max(0.0, min(my_budget, target))

    # If budget is tiny, still bid enough to avoid wasting turn when urgent
    if my_budget <= 10.0:
        if my_hp <= 2 or my_no_water_days >= 2:
            bid = my_budget
        else:
            bid = min(my_budget, 5.0)

    return float(bid)

